-- Workforce Hub: groups of partners with members and updates. Additive. Applied 2026-11-18.
CREATE TABLE IF NOT EXISTS "PartnerGroup" ("id" TEXT NOT NULL, "institutionId" TEXT NOT NULL, "name" TEXT NOT NULL, "purpose" TEXT, "createdBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PartnerGroup_pkey" PRIMARY KEY ("id"), CONSTRAINT "PartnerGroup_institutionId_fkey" FOREIGN KEY ("institutionId") REFERENCES "Institution"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "PartnerGroup_institutionId_idx" ON "PartnerGroup"("institutionId");
CREATE TABLE IF NOT EXISTS "PartnerGroupMember" ("id" TEXT NOT NULL, "groupId" TEXT NOT NULL, "partnerId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PartnerGroupMember_pkey" PRIMARY KEY ("id"), CONSTRAINT "PartnerGroupMember_groupId_fkey" FOREIGN KEY ("groupId") REFERENCES "PartnerGroup"("id") ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT "PartnerGroupMember_partnerId_fkey" FOREIGN KEY ("partnerId") REFERENCES "EcosystemPartner"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX IF NOT EXISTS "PartnerGroupMember_groupId_partnerId_key" ON "PartnerGroupMember"("groupId", "partnerId");
CREATE INDEX IF NOT EXISTS "PartnerGroupMember_partnerId_idx" ON "PartnerGroupMember"("partnerId");
CREATE TABLE IF NOT EXISTS "PartnerGroupPost" ("id" TEXT NOT NULL, "groupId" TEXT NOT NULL, "body" TEXT NOT NULL, "createdBy" TEXT NOT NULL, "authorLabel" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PartnerGroupPost_pkey" PRIMARY KEY ("id"), CONSTRAINT "PartnerGroupPost_groupId_fkey" FOREIGN KEY ("groupId") REFERENCES "PartnerGroup"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "PartnerGroupPost_groupId_createdAt_idx" ON "PartnerGroupPost"("groupId", "createdAt");
